fn days_to_next_sunday(day: &str) -> i8 {
    // Map each day abbreviation to an integer index (Sunday = 0)
    let day_index = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => panic!("Invalid day input"), // input assumed valid from problem description
    };

    let diff = (7 - day_index) % 7;
    if diff == 0 {
        7
    } else {
        diff
    }
}